def transform(grid):
    # Find the separator row (all zeros)
    sep = -1
    for i, row in enumerate(grid):
        if all(cell == 0 for cell in row):
            sep = i
            break

    top_rows = grid[:sep]
    bottom_rows = grid[sep+1:]

    output_rows = len(bottom_rows)
    cols = len(grid[0])
    output = []

    for r in range(output_rows):
        output_row = []
        for c in range(cols):
            top_val = top_rows[r][c]
            bot_val = bottom_rows[r][c]

            if top_val == bot_val:
                output_row.append(3)
            else:
                output_row.append(4)

        output.append(output_row)

    return output
